fn decode_checkpoint_box(bytes: &[u8]) -> Result<Box<PoolV1PairForestCheckpointV1>, ProgramError> {
    assert!(core::mem::size_of::<PoolV1PairForestCheckpointV1>()==176,"exact Box layout bytes");
    assert!(core::mem::align_of::<PoolV1PairForestCheckpointV1>()==8,"exact Box layout alignment");
    let raw=decode_pool_v1_pair_forest_checkpoint_v1(bytes);
    let mut allocated: *const PoolV1PairForestCheckpointV1=core::ptr::null();
    let mut out=(|| {let b=Box::new(raw.map_err(|_| ProgramError::InvalidAccountData)?);allocated=&*b;Ok(b)})();

    if let Ok(ref mut b)=out { let second=Box::new(**b); **b=**b;out=Ok(second); }
    match (&raw,&out) {
     (Ok(a),Ok(b))=>{ assert!(core::ptr::eq(&**b,allocated),"same Box allocation");assert!(!core::ptr::eq(&**b,a),"fresh owned carrier");assert!(a.bump==b.bump,"unchanged allocation payload"); },
     (Err(_),Err(e))=>{assert!(*e==ProgramError::InvalidAccountData,"mapped error");assert!(allocated.is_null(),"no allocation on decoder error");},
     _=>assert!(false,"same Result arm")
    }
    out
}
